Here is the commit message:
binder: fix max_thread type inconsistency
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

The type defined for the BINDER_SET_MAX_THREADS ioctl was changed from
size_t to __u32 in order to avoid incompatibility issues between 32 and
64-bit kernels. However, the internal types used to copy from user and
store the value were never updated. Use u32 to fix the inconsistency.

Fixes: a9350fc859ae ("staging: android: binder: fix BINDER_SET_MAX_THREADS declaration")
Reported-by: Arve Hjønnevåg <arve@android.com>
Cc: stable@vger.kernel.org
Signed-off-by: Carlos Llamas <cmllamas@google.com>
Reviewed-by: Alice Ryhl <aliceryhl@google.com>
Link: https://lore.kernel.org/r/20240421173750.3117808-1-cmllamas@google.com
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by a type inconsistency between the `BINDER_SET_MAX_THREADS` ioctl definition, which was changed to `__u32`, and the internal handling of the `max_threads` variable, which was still defined as `int`. This inconsistency could lead to incorrect data being processed, especially when interacting with user space, potentially causing issues in 32-bit and 64-bit kernel compatibility.

Here is the patch:

 static long binder_ioctl(struct file *filp, unsigned int cmd, unsigned long arg)
 {
 	int ret;
 	struct binder_proc *proc = filp->private_data;
 	struct binder_thread *thread;
 	void __user *ubuf = (void __user *)arg;

 	/*pr_info("binder_ioctl: %d:%d %x %lx\n",
 			proc->pid, current->pid, cmd, arg);*/

 	binder_selftest_alloc(&proc->alloc);

 	trace_binder_ioctl(cmd, arg);

 	ret = wait_event_interruptible(binder_user_error_wait, binder_stop_on_user_error < 2);
 	if (ret)
 		goto err_unlocked;

 	thread = binder_get_thread(proc);
 	if (thread == NULL) {
 		ret = -ENOMEM;
 		goto err;
 	}

 	switch (cmd) {
 	case BINDER_WRITE_READ:
 		ret = binder_ioctl_write_read(filp, arg, thread);
 		if (ret)
 			goto err;
 		break;
 	case BINDER_SET_MAX_THREADS: {
-		int max_threads;
+		u32 max_threads;

 		if (copy_from_user(&max_threads, ubuf,
 				   sizeof(max_threads))) {
 			ret = -EINVAL;
 			goto err;
 		}
 		binder_inner_proc_lock(proc);
 		proc->max_threads = max_threads;
 		binder_inner_proc_unlock(proc);
 		break;
 	}
 	case BINDER_SET_CONTEXT_MGR_EXT: {
 		struct flat_binder_object fbo;

 		if (copy_from_user(&fbo, ubuf, sizeof(fbo))) {
 			ret = -EINVAL;
 			goto err;
 		}
 		ret = binder_ioctl_set_ctx_mgr(filp, &fbo);
 		if (ret)
 			goto err;
 		break;
 	}
 	case BINDER_SET_CONTEXT_MGR:
 		ret = binder_ioctl_set_ctx_mgr(filp, NULL);
 		if (ret)
 			goto err;
 		break;
 	case BINDER_THREAD_EXIT:
 		binder_debug(BINDER_DEBUG_THREADS, "%d:%d exit\n",
 			     proc->pid, thread->pid);
 		binder_thread_release(proc, thread);
 		thread = NULL;
 		break;
 	case BINDER_VERSION: {
 		struct binder_version __user *ver = ubuf;

 		if (put_user(BINDER_CURRENT_PROTOCOL_VERSION,
 			     &ver->protocol_version)) {
 			ret = -EINVAL;
 			goto err;
 		}
 		break;
 	}
 	case BINDER_GET_NODE_INFO_FOR_REF: {
 		struct binder_node_info_for_ref info;

 		if (copy_from_user(&info, ubuf, sizeof(info))) {
 			ret = -EFAULT;
 			goto err;
 		}

 		ret = binder_ioctl_get_node_info_for_ref(proc, &info);
 		if (ret < 0)
 			goto err;

 		if (copy_to_user(ubuf, &info, sizeof(info))) {
 			ret = -EFAULT;
 			goto err;
 		}

 		break;
 	}
 	case BINDER_GET_NODE_DEBUG_INFO: {
 		struct binder_node_debug_info info;

 		if (copy_from_user(&info, ubuf, sizeof(info))) {
 			ret = -EFAULT;
 			goto err;
 		}

 		ret = binder_ioctl_get_node_debug_info(proc, &info);
 		if (ret < 0)
 			goto err;

 		if (copy_to_user(ubuf, &info, sizeof(info))) {
 			ret = -EFAULT;
 			goto err;
 		}
 		break;
 	}
 	case BINDER_FREEZE: {
 		struct binder_freeze_info info;
 		struct binder_proc **target_procs = NULL, *target_proc;
 		int target_procs_count = 0, i = 0;

 		ret = 0;

 		if (copy_from_user(&info, ubuf, sizeof(info))) {
 			ret = -EFAULT;
 			goto err;
 		}

 		mutex_lock(&binder_procs_lock);
 		hlist_for_each_entry(target_proc, &binder_procs, proc_node) {
 			if (target_proc->pid == info.pid)
 				target_procs_count++;
 		}

 		if (target_procs_count == 0) {
 			mutex_unlock(&binder_procs_lock);
 			ret = -EINVAL;
 			goto err;
 		}

 		target_procs = kcalloc(target_procs_count,
 				       sizeof(struct binder_proc *),
 				       GFP_KERNEL);

 		if (!target_procs) {
 			mutex_unlock(&binder_procs_lock);
 			ret = -ENOMEM;
 			goto err;
 		}

 		hlist_for_each_entry(target_proc, &binder_procs, proc_node) {
 			if (target_proc->pid != info.pid)
 				continue;

 			binder_inner_proc_lock(target_proc);
 			target_proc->tmp_ref++;
 			binder_inner_proc_unlock(target_proc);

 			target_procs[i++] = target_proc;
 		}
 		mutex_unlock(&binder_procs_lock);

 		for (i = 0; i < target_procs_count; i++) {
 			if (ret >= 0)
 				ret = binder_ioctl_freeze(&info,
 							  target_procs[i]);

 			binder_proc_dec_tmpref(target_procs[i]);
 		}

 		kfree(target_procs);

 		if (ret < 0)
 			goto err;
 		break;
 	}
 	case BINDER_GET_FROZEN_INFO: {
 		struct binder_frozen_status_info info;

 		if (copy_from_user(&info, ubuf, sizeof(info))) {
 			ret = -EFAULT;
 			goto err;
 		}

 		ret = binder_ioctl_get_freezer_info(&info);
 		if (ret < 0)
 			goto err;

 		if (copy_to_user(ubuf, &info, sizeof(info))) {
 			ret = -EFAULT;
 			goto err;
 		}
 		break;
 	}
 	case BINDER_ENABLE_ONEWAY_SPAM_DETECTION: {
 		uint32_t enable;

 		if (copy_from_user(&enable, ubuf, sizeof(enable))) {
 			ret = -EFAULT;
 			goto err;
 		}
 		binder_inner_proc_lock(proc);
 		proc->oneway_spam_detection_enabled = (bool)enable;
 		binder_inner_proc_unlock(proc);
 		break;
 	}
 	case BINDER_GET_EXTENDED_ERROR:
 		ret = binder_ioctl_get_extended_error(thread, ubuf);
 		if (ret < 0)
 			goto err;
 		break;
 	default:
 		ret = -EINVAL;
 		goto err;
 	}
 	ret = 0;
 err:
 	if (thread)
 		thread->looper_need_return = false;
 	wait_event_interruptible(binder_user_error_wait, binder_stop_on_user_error < 2);
 	if (ret && ret != -EINTR)
 		pr_info("%d:%d ioctl %x %lx returned %d\n", proc->pid, current->pid, cmd, arg, ret);
 err_unlocked:
 	trace_binder_ioctl_done(ret);
 	return ret;
 }



